final_sql:
SELECT s.School, s.DOCType
FROM frpm f JOIN schools s ON s.CDSCode = f.CDSCode
WHERE f."Charter Funding Type" = 'Locally funded'
AND (f."Enrollment (K-12)" - f."Enrollment (Ages 5-17)") > (
  SELECT AVG("Enrollment (K-12)" - "Enrollment (Ages 5-17)") FROM frpm WHERE "Charter Funding Type" = 'Locally funded'
);

SELECT s.AdmFName1 || ' ' || s.AdmLName1
FROM schools s JOIN satscores sc ON s.CDSCode = sc.cds
ORDER BY sc.NumGE1500 DESC LIMIT 1;

SELECT CAST(SUM(CASE WHEN "DOCType" = 'Unified School District' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN "DOCType" = 'Elementary School District' THEN 1 ELSE 0 END) AS ratio
FROM schools
WHERE "StatusType" = 'Merged' AND "County" = 'Orange';

SELECT SUM(f.`Enrollment (Ages 5-17)`)
FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode
WHERE s.City = 'Fremont' AND f.`School Type` = 'State Special Schools' AND f.`Academic Year` = '2014-2015';

SELECT SUM(f."Enrollment (Ages 5-17)")
FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode
WHERE s.City='Fremont' AND f."School Type"='State Special Schools';

SELECT sc.AdmFName1 || ' ' || sc.AdmLName1 AS full_name
FROM satscores sa JOIN schools sc ON sa.cds = sc.CDSCode
ORDER BY sa.NumGE1500 DESC LIMIT 1;

SELECT AVG(sa.NumTstTakr)
FROM schools s JOIN satscores sa ON s.CDSCode = sa.cds
WHERE s.County = 'Fresno' AND strftime('%Y', s.OpenDate) = '1980';

SELECT f.`School Name`
FROM frpm f JOIN satscores s ON f.CDSCode = s.cds
WHERE f.`Percent (%) Eligible Free (K-12)` > 0.1 AND s.NumGE1500 > 0;

SELECT TRIM(COALESCE(s.AdmFName1,'') || ' ' || COALESCE(s.AdmLName1,'')) AS FullName
FROM satscores ss JOIN schools s ON ss.cds = s.CDSCode
ORDER BY ss.NumGE1500 DESC LIMIT 1;

SELECT f.`School Name`, s.MailStreet, s.MailCity, s.MailState, s.MailZip
FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode
WHERE f.`County Name`='Monterey' AND f.`School Type`='High Schools (Public)' AND f.`FRPM Count (Ages 5-17)`>800;

SELECT s.AdmFName1 || ' ' || s.AdmLName1 AS full_name
FROM satscores ss JOIN schools s ON ss.cds = s.CDSCode
ORDER BY ss.NumGE1500 DESC LIMIT 1;

SELECT SUM(f."Enrollment (Ages 5-17)")
FROM frpm f JOIN schools s ON f.CDSCode=s.CDSCode
WHERE s.City='Fremont' AND s.EdOpsCode='SSS' AND f."Academic Year"='2014-2015';

SELECT SUM(f.`Enrollment (Ages 5-17)`)
FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode
WHERE f.`School Type` = 'State Special Schools' AND s.City = 'Fremont';
